using System;using System.IO;using System.Threading;using System.Threading.Tasks;using System.Diagnostics;using ProjectBattleAuto;
class Stall:MemoryStream {public override Task<int> ReadAsync(byte[] b,int o,int c,CancellationToken t){return new TaskCompletionSource<int>().Task;}}
class TimeoutIntegration {static void Main(){var watch=Stopwatch.StartNew();try{Engine.ReadWithTimeout(new Stall(),new byte[8],CancellationToken.None,100).GetAwaiter().GetResult();throw new Exception();}catch(IOException){}if(watch.ElapsedMilliseconds>2000)throw new Exception("stall");Console.WriteLine("PASS stalled transport ignoring cancellation");using(var c=new CancellationTokenSource()){c.Cancel();try{Engine.ReadWithTimeout(new Stall(),new byte[8],c.Token,1000).GetAwaiter().GetResult();throw new Exception();}catch(OperationCanceledException){}}Console.WriteLine("PASS cancellation");Engine.Root=Path.Combine(Path.GetTempPath(),"pb-lock-"+Guid.NewGuid());Directory.CreateDirectory(Engine.Root);using(var f=new FileStream(Path.Combine(Engine.Root,"install.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){try{Engine.Commit("absent",new Release());throw new Exception();}catch(IOException e){if(!e.Message.Contains("уже"))throw;}}Console.WriteLine("PASS simultaneous commit blocked");}}
